import re
import json
from docx import Document
from docx.oxml.ns import qn


def get_para_full_text(para):
    return ''.join(run.text for run in para.runs)


def replace_in_paragraph(para, data):
    """Replace all {{KEY}} placeholders in a paragraph, handling split runs."""
    full_text = get_para_full_text(para)
    pattern = r'\{\{([A-Z_]+)\}\}'

    if not re.search(pattern, full_text):
        return

    new_text = full_text
    for match in re.finditer(pattern, full_text):
        key = match.group(1)
        placeholder = match.group(0)
        if key in data:
            new_text = new_text.replace(placeholder, str(data[key]))

    if new_text != full_text and para.runs:
        # Preserve formatting of first run, consolidate all text there
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ''


def process_table(table, data):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                replace_in_paragraph(para, data)
            for nested_table in cell.tables:
                process_table(nested_table, data)


def remove_paragraph(para):
    """Remove a paragraph element from its parent."""
    p = para._element
    p.getparent().remove(p)


def handle_conditional_relocation(doc, include):
    """
    Find paragraphs containing {{IF_RELOCATION}}...{{END_IF_RELOCATION}}.
    If include=True: strip the markers but keep the content.
    If include=False: remove the entire paragraph(s) containing the block.
    Also removes 'Mobility Support:' header paragraph when not including.
    """
    start_marker = '{{IF_RELOCATION}}'
    end_marker = '{{END_IF_RELOCATION}}'

    paras_to_remove = []

    for para in doc.paragraphs:
        text = get_para_full_text(para)
        if start_marker in text or end_marker in text:
            paras_to_remove.append(para)

    if include:
        # Strip markers, keep content between them
        for para in paras_to_remove:
            full_text = get_para_full_text(para)
            new_text = full_text.replace(start_marker, '').replace(end_marker, '')
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
    else:
        # Remove each paragraph that contains a marker
        # Also remove the "Mobility Support:" header that precedes them
        for para in doc.paragraphs:
            text = para.text.strip()
            if text == 'Mobility Support:':
                # Check if next sibling is the conditional block
                paras_to_remove.insert(0, para)
                break

        for para in paras_to_remove:
            remove_paragraph(para)


def fill_template(template_path, data, output_path):
    doc = Document(template_path)

    # Determine relocation flag
    include_relocation = data.get('RELOCATION_PACKAGE', 'No').strip().lower() == 'yes'

    # Handle conditional section first (before placeholder replacement)
    handle_conditional_relocation(doc, include_relocation)

    # Replace placeholders in main body paragraphs
    for para in doc.paragraphs:
        replace_in_paragraph(para, data)

    # Replace placeholders in tables (including nested)
    for table in doc.tables:
        process_table(table, data)

    # Replace placeholders in headers and footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            replace_in_paragraph(para, data)
        for para in section.footer.paragraphs:
            replace_in_paragraph(para, data)

    doc.save(output_path)
    print(f'Saved: {output_path}')


# Load data
with open('/root/employee_data.json') as f:
    data = json.load(f)

fill_template(
    '/root/offer_letter_template.docx',
    data,
    '/root/offer_letter_filled.docx'
)

